//! The C source of a Lua module: `require("<namespace>")` loads `luaopen_<namespace>`.

use std::fmt::Write;

use uniffi_bindgen::interface::{AsType, Object, Type};

use super::module::Receiver;
use super::names::{ident, string_literal};
use super::types::Gen;

impl Gen<'_> {
    pub(crate) fn emit_source(&self) -> String {
        let p = &self.prefix;
        let ns = self.ci.namespace();
        let mut out = format!(
            "/* This file was autogenerated by uniffi-bindgen-lua. Do not edit it by hand.\n *\n * The Lua module `{ns}`: build it as a shared library named `{ns}` (with this\n * file, linking the Rust library) and `require(\"{ns}\")`. */\n\n#include \"uniffi_lua.h\"\n\n"
        );
        out.push_str(&self.emit_ffi_declarations());
        // External objects: their handles are cloned and freed through their own crate.
        for t in self.all_types() {
            if let Type::Object { .. } = &t
                && self.ci.is_external(&t)
                && let Some(obj) = self.object_def(&t)
            {
                let _ = writeln!(
                    out,
                    "extern uint64_t {}(uint64_t handle, RustCallStatus *out_status);",
                    obj.ffi_object_clone().name()
                );
                let _ = writeln!(
                    out,
                    "extern void {}(uint64_t handle, RustCallStatus *out_status);",
                    obj.ffi_object_free().name()
                );
            }
        }
        let _ = write!(
            out,
            "\ntypedef struct {p}_object {{\n    uint64_t handle;\n}} {p}_object;\n\n/* Shared with the other modules of the Lua state (uniffi_lua_shared_dispatcher). */\nstatic uniffi_lua_dispatcher *{p}_shared_dispatcher;\n#define {p}_dispatcher (*{p}_shared_dispatcher)\n\n/* Every call from Lua: remember the calling state, run queued callbacks. */\nstatic void {p}_enter(lua_State *L) {{\n    {p}_dispatcher.L = L;\n    uniffi_lua_service(&{p}_dispatcher);\n}}\n\n"
        );
        out.push_str(&self.emit_buffers());
        let _ = write!(
            out,
            "/* Raises the Lua error for a failed call; `push_error` pushes the declared error. */\nstatic UNIFFI_MAYBE_UNUSED int {p}_raise(lua_State *L, RustCallStatus *status, void (*push_error)(lua_State *, RustBuffer)) {{\n    switch (status->code) {{\n        case UNIFFI_CALL_ERROR:\n            if (push_error) {{\n                push_error(L, status->error_buf);\n                return lua_error(L);\n            }}\n            uniffi_buffer_free(status->error_buf);\n            return luaL_error(L, \"an unexpected error\");\n        case UNIFFI_CALL_UNEXPECTED_ERROR: {{\n            RustBuffer b = status->error_buf;\n            lua_pushliteral(L, \"rust panic: \");\n            lua_pushlstring(L, b.data ? (const char *)b.data : \"\", (size_t)b.len);\n            uniffi_buffer_free(b);\n            lua_concat(L, 2);\n            return lua_error(L);\n        }}\n        case UNIFFI_CALL_CANCELLED:\n            return luaL_error(L, \"the call was cancelled\");\n        default:\n            return luaL_error(L, \"unknown call status %d\", (int)status->code);\n    }}\n}}\n\n"
        );
        // Prototypes: the converters call these.
        for t in self.all_types() {
            let m = self.mangle(&t);
            match &t {
                Type::Object { .. } => {
                    let _ = writeln!(
                        out,
                        "static UNIFFI_MAYBE_UNUSED void {p}_push_{m}(lua_State *L, uint64_t handle);\nstatic UNIFFI_MAYBE_UNUSED uint64_t {p}_lower_{m}(lua_State *L, int idx, const char *what);"
                    );
                }
                Type::CallbackInterface { .. } => {
                    let _ = writeln!(
                        out,
                        "static UNIFFI_MAYBE_UNUSED void {p}_push_{m}(lua_State *L, uint64_t handle);\nstatic UNIFFI_MAYBE_UNUSED uint64_t {p}_lower_{m}(lua_State *L, int idx, const char *what);"
                    );
                }
                _ => {}
            }
        }
        out.push('\n');
        if self.has_async_callbacks() {
            out.push_str("static void uniffi_foreign_future_dropped(uint64_t handle) {\n    (void)handle;\n}\n\n");
        }
        // Lua implementations first: object helpers dispatch to them.
        for cb in self.ci.callback_interface_definitions() {
            out.push_str(&self.emit_impl_handles(&cb.as_type(), false));
        }
        for obj in self.ci.object_definitions() {
            if obj.has_callback_interface() {
                out.push_str(&self.emit_impl_handles(&obj.as_type(), true));
            }
        }
        for t in self.all_types() {
            if let Type::Object { .. } = &t {
                out.push_str(&self.emit_object_helpers(&t));
            }
        }
        out.push_str(&self.emit_converters());
        for cb in self.ci.callback_interface_definitions() {
            out.push_str(&self.emit_vtable(
                &cb.as_type(),
                &cb.vtable_methods(),
                cb.ffi_init_callback().name(),
                &self.ffi_type(&cb.vtable()),
            ));
        }
        for obj in self.ci.object_definitions() {
            if obj.has_callback_interface()
                && let Some(vtable) = obj.vtable()
            {
                out.push_str(&self.emit_vtable(
                    &obj.as_type(),
                    &obj.vtable_methods(),
                    obj.ffi_init_callback().name(),
                    &self.ffi_type(&vtable),
                ));
            }
        }
        let (errors, error_register) = self.emit_error_helpers();
        out.push_str(&errors);

        let mut register = String::new();
        let mut functions: Vec<(String, String)> = Vec::new();
        for f in self.ci.function_definitions() {
            let cname = format!("{p}_fn_{}", ident(f.name()));
            out.push_str(&self.lua_function(f, &cname, &Receiver::None, f.name()));
            functions.push((f.name().to_owned(), cname));
        }
        for obj in self.ci.object_definitions() {
            let (code, reg) = self.emit_object(obj);
            out.push_str(&code);
            register.push_str(&reg);
        }
        for r in self.ci.record_definitions() {
            let t = r.as_type();
            if self.has_value_methods(&t) {
                let (code, reg) = self.emit_value_type(
                    &t,
                    r.constructors(),
                    r.methods(),
                    &r.uniffi_trait_methods(),
                );
                out.push_str(&code);
                register.push_str(&reg);
            }
        }
        for e in self.ci.enum_definitions() {
            let t = e.as_type();
            if self.has_value_methods(&t) {
                let (code, reg) = self.emit_value_type(
                    &t,
                    e.constructors(),
                    e.methods(),
                    &e.uniffi_trait_methods(),
                );
                out.push_str(&code);
                register.push_str(&reg);
            }
        }
        out.push_str(&self.emit_luaopen(&functions, &register, &error_register));
        out
    }

    fn emit_buffers(&self) -> String {
        format!(
            "static UNIFFI_MAYBE_UNUSED RustBuffer uniffi_buffer_from(const void *data, size_t len) {{\n    if (len > INT32_MAX) {{\n        fputs(\"uniffi: a buffer is longer than 2^31-1\\n\", stderr);\n        abort();\n    }}\n    ForeignBytes bytes;\n    bytes.len = (int32_t)len;\n    bytes.data = (const uint8_t *)data;\n    RustCallStatus status = {{0}};\n    RustBuffer buffer = {from}(bytes, &status);\n    if (status.code != UNIFFI_CALL_SUCCESS) {{\n        fputs(\"uniffi: could not allocate a RustBuffer\\n\", stderr);\n        abort();\n    }}\n    return buffer;\n}}\n\nstatic UNIFFI_MAYBE_UNUSED void uniffi_buffer_free(RustBuffer buffer) {{\n    RustCallStatus status = {{0}};\n    {free}(buffer, &status);\n}}\n\n",
            from = self.ci.ffi_rustbuffer_from_bytes().name(),
            free = self.ci.ffi_rustbuffer_free().name(),
        )
    }

    fn emit_luaopen(
        &self,
        functions: &[(String, String)],
        register: &str,
        error_register: &str,
    ) -> String {
        let p = &self.prefix;
        let ns = self.ci.namespace();
        let mut checks = String::new();
        let _ = writeln!(
            checks,
            "        if ({}() != {}) {{\n            return luaL_error(L, \"{ns}: contract version mismatch, rebuild the module for this library\");\n        }}",
            self.ci.ffi_uniffi_contract_version().name(),
            self.ci.uniffi_contract_version()
        );
        if !self.config.omit_checksums {
            for (name, expected) in self.ci.iter_checksums() {
                let _ = writeln!(
                    checks,
                    "        if ({name}() != {expected}) {{\n            return luaL_error(L, \"{ns}: API checksum mismatch, rebuild the module and the library together\");\n        }}"
                );
            }
        }
        for cb in self.ci.callback_interface_definitions() {
            let _ = writeln!(checks, "        {p}_{}_init();", self.mangle(&cb.as_type()));
        }
        for obj in self
            .ci
            .object_definitions()
            .iter()
            .filter(|o| Object::has_callback_interface(o))
        {
            let _ = writeln!(
                checks,
                "        {p}_{}_init();",
                self.mangle(&obj.as_type())
            );
        }
        let mut fns = String::new();
        for (n, f) in functions {
            let _ = writeln!(
                fns,
                "    lua_pushcfunction(L, {f});\n    lua_setfield(L, -2, {});",
                string_literal(n)
            );
        }
        format!(
            "static int {p}_poll(lua_State *L) {{\n    {p}_enter(L);\n    return 0;\n}}\n\nint luaopen_{id}(lua_State *L);\n\nint luaopen_{id}(lua_State *L) {{\n    static bool loaded = false;\n    if (!loaded) {{\n{checks}        {p}_shared_dispatcher = uniffi_lua_shared_dispatcher(L);\n        loaded = true;\n    }} else if ({p}_dispatcher.L != L && !uniffi_lua_on_owner(&{p}_dispatcher)) {{\n        return luaL_error(L, \"{ns}: the module serves one Lua state, on the thread that loaded it\");\n    }}\n    {p}_dispatcher.L = L;\n{error_register}    lua_newtable(L);\n{fns}    lua_pushcfunction(L, {p}_poll);\n    lua_setfield(L, -2, \"poll\");\n{register}    return 1;\n}}\n",
            id = ident(ns)
        )
    }
}
